fn main() { let scale: f32 = std::env::args().nth(1).unwrap().parse().unwrap(); let frames = sdocx::pencil_atlas_probe(scale); eprintln!("{} stamps", frames.len()); let bytes: Vec<u8> = frames.into_iter().flatten().flatten().collect(); use std::io::Write; let mut f = std::fs::OpenOptions::new().write(true).create_new(true).open(std::env::args().nth(2).unwrap()).unwrap(); f.write_all(&bytes).unwrap(); }
